      "most_likely_effort": 6
    },
    {
      "activity_id": "ACT-6",
      "activity_name": "Reactor Stream Processor Module (U6)",
      "activity_description": "Build the reactor-stream processor module supporting time-windowing (--timeWindow), field selection, dynamic aggregation expressions (min, avg), and integration with external streams.",
      "most_likely_effort": 7
    },
    {
      "activity_id": "ACT-7",
      "activity_name": "Microbatching Capability Implementation (U7)",
      "activity_description": "Implement microbatching support across modules with configurable batch intervals (--batchInterval) for improved throughput performance.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "ACT-8",
      "activity_name": "Performance Testing Infrastructure & Benchmarking (U8)",
      "activity_description": "Set up performance test environment on Rackspace, script automated benchmark suites, and establish baseline performance metrics for Kafka sources and Spring XD pipelines.",
